    const L = {};
    L.bg = WHITE;
    L.surface = WHITE;
    L['surface-2'] = N(0.975);
    L['surface-3'] = N(0.95);
    L.line = N(0.915);
    L['line-strong'] = N(0.85);
    L.fg = N(0.22);
    L['fg-2'] = N(0.4);
    L['fg-3'] = ensureContrast(N(0.53), WHITE, 4.5);

    L.brand = P;
    L['brand-ink'] = onColor(P);
    L['brand-hover'] = shiftL(P, p.l > 0.45 ? -0.06 : 0.05);
    L['brand-soft'] = mix(P, WHITE, 0.9);
